import { useCallback } from 'react';

export default function DungeonInventoryModal({ isOpen = false, hero = null, onClose }) {
    const handleClose = useCallback(() => {
        if (typeof onClose === 'function') {
            onClose();
        }
    }, [onClose]);

    if (!isOpen || !hero) {
        return null;
    }

    const heroData = hero.hero || {};
    // Fallback to 'classe' or 'portrait' if 'nome' or 'immagine' are missing in the actual domain object
    const heroName = heroData.nome || heroData.classe || 'Eroe Sconosciuto';
    const heroImage = heroData.immagine || heroData.portrait || heroData.miniature || '';
    const heroClass = heroData.classe || 'Classe Sconosciuta';

    return (
        <div 
            className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4"
            onClick={handleClose}
        >
            <div 
                className="bg-gray-900 text-white rounded-xl shadow-2xl max-w-[500px] w-full p-6 flex flex-col max-h-[90vh]"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex justify-between items-center mb-6 border-b border-gray-700 pb-3">
                    <h2 className="text-2xl font-bold">Inventario</h2>
                    <button 
                        onClick={handleClose}
                        className="text-gray-400 hover:text-white transition-colors text-3xl leading-none"
                        aria-label="Chiudi"
                    >
                        &times;
                    </button>
                </div>

                <div className="overflow-y-auto pr-2">
                    {/* Hero Identity */}
                    <div className="flex items-center gap-4 mb-6 bg-gray-800 p-4 rounded-lg">
                        {heroImage && (
                            <img 
                                src={`/img/personaggi/${heroImage}`} 
                                alt={heroName} 
                                className="w-16 h-16 object-cover rounded-full border-2 border-gray-600 bg-gray-700"
                            />
                        )}
                        <div>
                            <h3 className="text-xl font-bold text-yellow-500">{heroName}</h3>
                            <p className="text-sm text-gray-300">{heroClass}</p>
                        </div>
                    </div>

                    {/* Gold Balance */}
                    <div className="mb-6 bg-yellow-900/30 border border-yellow-700/50 p-4 rounded-lg flex items-center justify-between">
                        <span className="font-semibold text-yellow-500">Monete d'Oro:</span>
                        <span className="text-xl font-bold text-yellow-400">{hero.gold ?? 0}</span>
                    </div>

                    {/* Items Grid (Oggetti) */}
                    <div className="mb-6">
                        <h4 className="text-lg font-semibold mb-3 text-gray-200 border-b border-gray-700 pb-1">Oggetti</h4>
                        {(!hero.inventory || hero.inventory.length === 0) ? (
                            <p className="text-gray-500 italic text-sm">Nessun oggetto nell'inventario.</p>
                        ) : (
                            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                                {hero.inventory.map((item, index) => {
                                    // Handle both ID arrays and populated object arrays gracefully
                                    const isObj = typeof item === 'object' && item !== null;
                                    const id = isObj ? item.id : item;
                                    const name = isObj ? (item.nome || `Oggetto #${id}`) : `Oggetto #${id}`;
                                    const image = isObj ? item.immagine : null;

                                    return (
                                        <div key={`item-${id}-${index}`} className="bg-gray-800 p-3 rounded-lg flex flex-col items-center text-center border border-gray-700">
                                            {image ? (
                                                <img src={`/img/oggetti/${image}`} alt={name} className="w-10 h-10 object-contain mb-2" />
                                            ) : (
                                                <div className="w-10 h-10 bg-gray-700 rounded-full mb-2 flex items-center justify-center text-xs text-gray-400">
                                                    {id}
                                                </div>
                                            )}
                                            <span className="text-sm text-gray-300">{name}</span>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                    {/* Equipment List (Equipaggiamento) */}
                    <div>
                        <h4 className="text-lg font-semibold mb-3 text-gray-200 border-b border-gray-700 pb-1">Equipaggiamento</h4>
                        {(!hero.equipment || hero.equipment.length === 0) ? (
                            <p className="text-gray-500 italic text-sm">Nessun equipaggiamento.</p>
                        ) : (
                            <ul className="space-y-2">
                                {hero.equipment.map((eq, index) => {
                                    // Handle both ID arrays and populated object arrays gracefully
                                    const isObj = typeof eq === 'object' && eq !== null;
                                    const id = isObj ? eq.id : eq;
                                    const name = isObj ? (eq.nome || `Equipaggiamento #${id}`) : `Equipaggiamento #${id}`;

                                    return (
                                        <li key={`eq-${id}-${index}`} className="bg-gray-800 p-3 rounded-lg flex items-center border border-gray-700">
                                            <span className="w-2 h-2 bg-blue-500 rounded-full mr-3"></span>
                                            <span className="text-gray-300">{name}</span>
                                        </li>
                                    );
                                })}
                            </ul>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}